create policy tenants_read on public.tenants for select to authenticated using(private.member_of(id));
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or exists(select 1 from public.tenant_members m where m.user_id=profiles.id and private.has_permission(m.tenant_id,'team.view')));
