create table private.integration_credentials(tenant_id uuid not null references public.tenants(id), provider text not null, encrypted_secret text not null, external_account_id text, created_at timestamptz default now(), primary key(tenant_id,provider));
create table private.webhook_events(id uuid primary key default gen_random_uuid(), provider text not null, event_key text not null, tenant_id uuid references public.tenants(id), payload jsonb not null, status text not null default 'pending', attempts integer not null default 0, available_at timestamptz not null default now(), locked_at timestamptz, error_code text, created_at timestamptz not null default now(), unique(provider,event_key));
create table private.outbox(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), kind text not null, event_key text not null unique, payload jsonb not null, status text not null default 'pending', attempts integer not null default 0, available_at timestamptz not null default now(), locked_at timestamptz, created_at timestamptz not null default now());
create index outbox_pending on private.outbox(status,available_at);
create index webhooks_pending on private.webhook_events(status,available_at);
create table private.rate_limits(key text primary key, count integer not null, expires_at timestamptz not null);
create table private.geo_cache(key text primary key, tenant_id uuid not null references public.tenants(id), value jsonb not null, expires_at timestamptz not null);
create table private.push_subscriptions(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), user_id uuid not null references public.profiles(id), endpoint text not null, p256dh text not null, auth text not null, created_at timestamptz default now(), unique(tenant_id,user_id,endpoint));
create table private.billing_charges(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id), subscription_id uuid not null references public.subscriptions(id), provider_id text unique, idempotency_key uuid not null default gen_random_uuid(), amount_cents integer not null, status text not null default 'pending', pix_copy_paste text, hosted_url text, expires_at timestamptz, credited_at timestamptz, created_at timestamptz not null default now());
create unique index billing_open_charge on private.billing_charges(tenant_id) where status in ('pending','creating');
create table private.support_sessions(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), tenant_id uuid not null references public.tenants(id), reason text not null, expires_at timestamptz not null, ended_at timestamptz, created_at timestamptz default now());
revoke all on all tables in schema private from public,anon,authenticated;
-- Only selected, tenant-scoped tables participate in realtime.
do $$ declare n text; begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') then
  foreach n in array array['orders','conversations','conversation_messages','notifications','whatsapp_instances','tenant_members'] loop
   if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=n) then execute format('alter publication supabase_realtime add table public.%I',n); end if;
  end loop;
 end if;
end $$;
